class Solution:
    def subsequenceSumAfterCapping(self, nums, k):
        n = len(nums)
        ans = []
        for x in range(1, n + 1):
            dp = [False] * (k + 1)
            dp[0] = True
            for v in nums:
                v = min(v, x)
                for s in range(k, v - 1, -1):
                    if dp[s - v]:
                        dp[s] = True
            ans.append(dp[k])
        return ans

