class Solution {
public:
    vector<bool> subsequenceSumAfterCapping(vector<int>& nums, int k) {
        int n = nums.size();
        vector<bool> ans;
        for (int x = 1; x <= n; x++) {
            vector<char> dp(k + 1, 0);
            dp[0] = 1;
            for (int v : nums) {
                v = min(v, x);
                for (int s = k; s >= v; s--) if (dp[s - v]) dp[s] = 1;
            }
            ans.push_back(dp[k]);
        }
        return ans;
    }
};

