class Solution:
    def subsequenceSumAfterCapping(self, nums, k):
        n = len(nums)
        cnt = [0] * (n + 1)
        for v in nums:
            cnt[v] += 1
        dp = [False] * (k + 1)
        dp[0] = True
        ans = [False] * n
        gt = n
        for x in range(1, n + 1):
            gt -= cnt[x]
            for _ in range(cnt[x]):
                for s in range(k, x - 1, -1):
                    if dp[s - x]:
                        dp[s] = True
            t = 0
            while t * x <= k and t <= gt:
                if dp[k - t * x]:
                    ans[x - 1] = True
                    break
                t += 1
        return ans

